'use strict';
const $ = id => document.getElementById(id);
const views = {
 garage:['Garage overview','4D'], cars:['Cars / dealership','4D'], tuning:['Tuning','4E'], setups:['Saved configurations','4E'], maintenance:['Installed / service','4F'], inventory:['Inventory / transfers','4G'], shop:['Shop / trade cart','4H'], assemblies:['Engines / valuation','4I'], career:['Race selection / records','4J'], business:['Business / recovery','4K'], race:['Race / staging HUD','4L'], results:['Race results','4L'], settings:['Settings','4C'], sound:['Engine / sound bench','4M'], physical:['Physical driving bench','4N'], coverage:['Control coverage','4A']
};
let current='garage', state='healthy', settingTab='Audio', benchTab='Drive', draftDirty=false, cartCount=2, driveOwner='Keyboard', wearTab='Engine';
const annotations = {
 garage:['Overview first','Saved car, fuel and the most important failure stay above detail scrolling.','Same stats everywhere','Power, torque, weight and quarter-mile estimate use the installed build. Open full stats for strength and detailed tradeoffs.','Fast destinations','Practice, repair, tune and inspection are direct routes. Developer benches have a separate entry and isolated-state label.'],
 cars:['Exact owned instance','Same-model copies show their instance suffix, condition and reservations. Selection never conflates their inventories.','Ownership versus dealer','Owned cars and new offers are distinct tabs. Used component buyback stays in Workshop, not a fabricated used-car dealer.','Purchase terms','Preview package contents, initial resources and total price before confirming the existing paid operation.'],
 tuning:['Visible draft','UNAPPLIED and the fixed Apply/Revert bar distinguish preview edits from what races use. Leaving discards the draft.','Installed permissions','Fixed hardware shows a reason and an upgrade route instead of presenting an editable setting. No tune slider replaces a turbo kit.','Comparison stays visible','Current/proposed stats, units and warnings update in the summary; detailed probes stay bounded and asynchronous in Unity.'],
 setups:['Blueprint, not inventory','Saved configurations describe desired hardware and adjustments. They do not save health, fuel or ownership IDs.','Load preview','Show installed items kept, usable spares reused and missing purchases separately with the total cost.','Explicit publish','Apply owned or buy missing + apply uses the existing atomic transaction. No parts are taken from donor cars automatically.'],
 maintenance:['Failure first','List failed and service-needed parts before healthy slots. Failure consequences are component-specific.','Part and position','Whole kits are normal replacements; individual cylinder/valve/tire positions support targeted repair when the model allows it.','Service boundaries','Top-up adds liquid only. Repair eligibility, rebuild time, cost and reservation are explicit. Retained spares keep their wear.'],
 inventory:['One ownership view','Storage, car and engine trees reference actual IDs; the selected container never copies assets.','Condition and compatibility','Show wear, faults, matching role and actual destination. Explain fitment rejection before any move.','Staged move or immediate reuse','Move/sale commands can go to the trade cart; the existing deliberate reuse/install shortcut remains distinct.'],
 shop:['Offer → basket','Complete sets are selected by default and display their actual unit count. Individual buying does not require a cylinder choice.','Pinned cart and comparison','Charges, credits, net payment and cumulative stats stay visible across category changes. Used stock keeps real wear.','Position only for installation','Choose cylinder/valve/tire positions when installing individual units. Buying loose never demands a target. Confirm all publishes once.'],
 assemblies:['Actual engine tree','Partial trees and missing slots remain visible. Engine oils, fault history and IDs survive detach/transfer.','Quote explanations','Buyer, completeness, condition and assembly demand explain value; complete-engine pricing is not a sum-of-parts rule.','Keep/dispose confirmation','Show kept assets and the exact sale separately. Keeping an engine excludes its descendants from chassis sale.'],
 career:['Eligibility at selection','Show why the actual build can or cannot enter, including incomplete hardware and exact-car job reservations.','Entry terms before race','Fees, payout rules, distance and opponent settings stay distinct from the physics assists. Practice is clearly no payout.','Existing records','Last pass and recorded splits are inspectable; this phase does not invent a larger event roster.'],
 business:['Income and cap','Make capped claimable money and the active accrual contract readable without pretending it is live race income.','Exact reservations','Jobs name the exact car/engine and deadline. Claim/cancel releases the reservation through the existing transaction.','Recovery always reachable','No-car/no-cash recovery remains accessible independently of selecting a drivable vehicle.'],
 race:['Primary driving information','Speed, gear, RPM, installed shift lamp and lights dominate. Advanced coupling/contact/heat data is optional.','Neutral staging','W/Space raises revs while E engages under launch rules. Warm-up is optional and retains its physical heat, fuel and wear.','Independent inputs','Pedals stay held through shifts. Pause clears transient commands and never silently resumes on focus return.'],
 results:['Timing and settlement','Reaction, ET, splits, trap speed and reward status are distinct. No speculative reward is shown as paid.','Failure consequences','Show what failed and route directly to repairs; brake or branch failure does not claim the engine is destroyed.','Continue deliberately','Retry uses the retained car/fuel/wear and chosen temperature rules. Garage and repair commit actual run state once.'],
 settings:['Shared preferences','Master and opponent gain, units and controls are shared across races and benches. This review does not play or measure audio.','Independent simulation rules','Presets are shortcuts; advanced heat/wear/fuel/fluid/condition/assist controls remain separate. Continuous optimal heat disables start-only choices.','Reset without losing preferences','Confirmation resets progression/assets/tunes, retains driving/audio/units/input preferences and does not fire on selection.'],
 sound:['Sound fixture label','Fixed RPM, dyno resistance and artificial roller/slip inputs are visible as diagnostics, not full road simulation.','Ownership is local','Only operating controls are feedback when keyboard owns them; engine/turbo/exhaust/mix remain editable. A slider edit deliberately takes control.','Repeatable audition','Scenario A/B, captures, chronological history and exports stay near the graph. The complete release tail is not dropped.'],
 physical:['Shared road simulation','This bench uses the race solver with installed protection, real wheel/contact/coupling and component failures. No payout or race cycle.','Record is optional','Recording OFF allows indefinite manual tests. Replay/scenario uses captured state; full chronological graphs include shifts and coast tails.','Destructive setup is isolated','Per-part condition/fault/liquid controls and wear multiplier affect only copied assets. Wear reset does not refill fuel/oil/coolant.'],
 coverage:['Source-backed migration','Explicit UI call sites, keyboard occurrences and reflected fields have source locations and destination phases.','Templates, not button counts','Catalog loops, per-cylinder positions, torque points and scenario loops expand at runtime. Counts do not certify Unity feature parity.','Phase-by-phase audit','Each migration must bind these controls, run relevant checks and receive user validation before removing its legacy view.']
};
const a = n => `<span class="annotation">${n}</span>`;
const btn = (text, action='', cls='', disabled=false) => `<button ${action} class="${cls}" ${disabled?'disabled':''}>${text}</button>`;
const route = (text,dest,cls='') => btn(text,`data-route="${dest}"`,cls);
const demo = (text,cls='',disabled=false) => btn(text,`data-demo="${text}"`,cls,disabled);
const title = (name,tag='Saved owned car') => `<div class="page-title"><h1>${name}</h1><span class="badge">${tag}</span></div>`;
const panel = (name,body,n=0) => `<section class="panel"><div class="panel-header"><h2>${n?a(n):''}${name}</h2></div>${body}</section>`;
const item = (heading,sub,actions='',cls='') => `<article class="item ${cls}"><h3>${heading}</h3><div class="muted">${sub}</div>${actions?`<div class="actions">${actions}</div>`:''}</article>`;
const options = (values,selected) => `<select>${values.map(s=>`<option ${s===selected?'selected':''}>${s}</option>`).join('')}</select>`;
function slider(name,value,min,max,unit='',attr='',disabled=false){return `<div class="field"><label><span>${name}</span><output>${value}${unit}</output></label><input type="range" aria-label="${name}" value="${value}" min="${min}" max="${max}" ${attr} ${disabled?'disabled':''}><div class="row"><small>${min}–${max}${unit}</small>${disabled?(attr.includes('data-drive-slider')?'<small>Keyboard/scenario feedback</small>':'<small>Fixed by installed hardware</small>'):'<small>Fine / Reset · numeric entry in Unity</small>'}</div></div>`;}
function car(){return `<div class="car-area" aria-label="Placeholder car render area"><svg viewBox="0 0 500 150" aria-hidden="true"><path d="M40 95L58 69L140 60L194 27L294 27L354 64L425 73L458 92L457 118L42 118Z" fill="#77999f" stroke="#b3ccd0" stroke-width="2"/><path d="M159 62L199 34L238 34L238 64ZM247 34L289 34L328 64L247 64Z" fill="#26373f"/><path d="M45 102L455 102" stroke="#47666e" stroke-width="3"/><g fill="#0f171b" stroke="#96a8af" stroke-width="4"><circle cx="125" cy="114" r="29"/><circle cx="374" cy="114" r="29"/></g><g fill="#849ba4"><circle cx="125" cy="114" r="15"/><circle cx="374" cy="114" r="15"/></g></svg></div>`;}
function metrics(compare=false){const shop=current==='shop';return `<div class="pin summary"><div><small>Power</small><strong>${state==='worn'?'216':'254'}${compare?(shop?' → 254':' → 278'):''}<small> hp</small></strong></div><div><small>Torque</small><strong>320${compare?(shop?' → 320':' → 351'):''}<small> Nm</small></strong></div><div><small>Race mass</small><strong>1,284${compare?(shop?' → 1,286':' → 1,296'):''}<small> kg</small></strong></div><div><small>¼-mile estimate</small><strong>${state==='incomplete'?'Unavailable':'14.2'+(compare?(shop?' → 14.2':' → 13.9'):'')}<small> s</small></strong></div></div>`;}
function stat(name,current,newValue,width,kind='positive'){const c=parseFloat(current.replaceAll(',','')),n=newValue?parseFloat(newValue.replaceAll(',','')):c;const scale=Number.isFinite(c)&&Number.isFinite(n)?Math.ceil(Math.max(c,n)/(width/100)):100;const cw=Number.isFinite(c)?c/scale*100:width,nw=Number.isFinite(n)?n/scale*100:cw;return `<div class="stat-row"><span>${name}</span><span class="delta ${kind}">${current}${newValue?' → '+newValue:''}${kind==='tradeoff'?' · tradeoff':''}</span><div class="bar"><span class="baseline" style="width:${cw}%"></span>${newValue&&nw!==cw?`<span class="change ${kind}" style="left:${Math.min(cw,nw)}%;width:${Math.abs(nw-cw)}%"></span>`:''}</div><small class="muted">Reference scale: 0–${scale} · not a safe limit</small></div>`;}
function stateNotice(){
 const t={healthy:['Ready','Installed build; saved adjustments.','ok'],worn:['Attention · clutch worn / rear brakes failed','Brakes reduce braking; engine is still operational. Open maintenance for specific remedies.','fail'],incomplete:['Cannot race · engine missing required parts','Partial builds remain owned. Reassemble using compatible inventory or bought hardware.','fail'],reserved:['Reserved · display job','This exact car and its fitted parts are locked until claim or cancellation. Inspection is available.',''],empty:['No owned car','Recovery work and dealerships remain available. Missing cars or OEM parts are never granted automatically.','']};
 const [h,s,c]=t[state];return `<div class="notice ${c}"><strong>${h}</strong><br><span class="muted">${s}</span></div>`;
}
function summaryPanel(compare=true){
 const shop=current==='shop';
 return panel('Build comparison',`${stat('Power','254 hp',compare?(shop?'254 hp':'278 hp'):'',60)}${stat('Torque','320 Nm',compare?(shop?'320 Nm':'351 Nm'):'',65)}${stat('Mass','1,284 kg',compare?(shop?'1,286 kg':'1,296 kg'):'',72,compare?'negative':'positive')}${shop?stat('Mechanical RPM strength','7,000 RPM','8,500 RPM',70):stat('Clutch headroom','18%',compare?'9%':'',38,compare?'tradeoff':'positive')}${dyno()}${shop?'<p class="tiny muted">Forged pistons change strength/mass, not healthy-engine horsepower. Overlapping current/proposed curves are intentional.</p>':''}<details><summary>All stats and explanations</summary><p>Cooling, torque strength, mass/inertia, gearing, grip, brake capacity, installed controls and sound tradeoffs.</p><p class="muted">Grey baseline and green/red/amber change segment share a labelled min–max scale. These bars illustrate layout only.</p></details>`,2);
}
function garage(){
 if(state==='empty')return title('Garage')+stateNotice()+panel('A way back',`<div class="empty"><h2>Your garage is empty</h2><p class="muted">Retained inventory may still contain spares or an engine.</p><div class="actions">${route('Recovery work','business','primary')}${route('Browse cars','cars')}${route('Inspect storage','inventory')}</div></div>`,1);
 return title('Garage')+stateNotice()+metrics()+`<div class="grid">${panel('Kestrel 2.0T · #8A21',car()+`<div class="row"><span>2.0 L · inline 4 · turbo · manual</span><span class="badge">C class</span></div><div class="actions">${route('Practice / no payout','race','primary')}${route('Choose event','career')}${route('Select another car','cars')}</div>`,1)}${panel('Ready for the next run',`${item('Fuel · 42 / 50 L','Fuel mass contributes to acceleration and grip.',route('Refuel / service','maintenance'))}${item('Parts · '+(state==='worn'?'2 need attention':'healthy'),'Engine, brakes and drive branches have separate consequences.',route('Inspect parts','maintenance'))}${item('Tune · saved','Preview first; Apply before racing.',route('Tune this car','tuning'))}`,3)}</div><div class="actions" style="margin-top:16px">${route('Full stats / dyno','tuning')}${route('Income / jobs','business')}${route('Engine / sound bench','sound')}${route('Physical bench / copied build','physical')}</div>`;
}
function dyno(live=false){
 const base='M40 184C110 166 174 124 234 87S356 42 399 40S471 47 522 92';
 const proposed=current==='shop'?base:'M40 178C110 163 174 119 234 75S356 28 399 27S471 35 522 77';
 const grey=live?'M40 181L91 180L102 146L145 126L170 105L173 168L184 126L228 94L255 80L258 164L272 101L318 71L355 65L370 118L405 173L431 181L521 183':base;
 const green=live?'M40 187L90 186L100 136L144 115L169 93L172 158L184 115L227 80L253 68L256 153L270 89L316 56L354 51L368 104L403 168L428 186L521 188':proposed;
 return `<svg class="plot" viewBox="0 0 540 225" role="img" aria-label="Illustrative ${live?'chronological full-run':'engine RPM'} graph, not measured performance"><g fill="none" stroke="#39454c" stroke-width="1"><path d="M40 20V192H522M40 58H522M40 98H522M40 138H522M120 20V192M220 20V192M320 20V192M420 20V192"/></g><g fill="#a8b8c1" font-size="12"><text x="8" y="24">hp</text><text x="42" y="215">${live?'0 s':'1,000'}</text><text x="254" y="215">${live?'6 s':'4,000 RPM'}</text><text x="468" y="215">${live?'12 s':'7,000'}</text></g><path d="${grey}" fill="none" stroke="#a8b8c1" stroke-width="2"/><path d="${green}" fill="none" stroke="#8edaca" stroke-width="3"/><path d="${live?grey:base}" fill="none" stroke="#8dbfe9" stroke-width="2" stroke-dasharray="5 3"/></svg><div class="legend"><span>Current${live?' run':''}</span><span class="proposed">${live?'Full trace':'Proposed'}</span><span class="renewed">${live?'Previous run':'Same build / no wear'}</span></div>`;
}
function cars(){return title('Cars & dealership','Exact owned instances')+stateNotice()+`<div class="grid equal">${panel('Owned cars',state==='empty'?'<div class="empty">No owned cars · recovery remains available</div>':`<div class="list">${item('Kestrel 2.0T · #8A21','Selected · 42 L fuel · '+(state==='reserved'?'job reserved':'18 passes'),demo('Select #8A21')+route('Inspect','garage'),'selected')}${item('Kestrel 2.0T · #B147','Different tune · 18 L fuel · worn tires',demo('Select #B147')+route('Buyer quote','assemblies'))}${item('AWD pickup · #E802','5.7 L V8 · 50:50 drive setup',demo('Select pickup'))}</div>`,1)}${panel('New dealership offers',car()+item('Kestrel OEM package','$12,000 · fuel/oil/coolant included · REP 0',demo('Inspect package')+btn('Review purchase','data-confirm="purchase"','primary'))+`<p class="tiny muted">Additional copies have independent hardware, wear and resources.</p>`,2)}</div>`;}
function tuning(){return title('Tuning',draftDirty?'UNAPPLIED DRAFT':'Saved values')+stateNotice()+metrics(true)+`<div class="grid">${panel('Adjustments',`<div class="tabs">${demo('Launch')}${demo('Gearing')}${demo('Induction')}${demo('Tires / mass')}${route('Saved configurations','setups')}</div><div class="scroll">${slider('Launch RPM',3500,900,6800,' RPM','data-tune="true"')}${slider('Auto shift RPM',6500,2400,6900,' RPM','data-tune="true"')}${slider('Tire pressure',30,18,42,' psi','data-tune="true"')}${slider('Boost multiplier',1,1,2,'×','data-tune="true"',true)}<p class="muted">Fixed wastegate: replace hardware to unlock boost adjustment.</p><div class="field"><label>Installed turbo</label><strong>Medium single turbo · size fixed</strong> ${route('Compare replacement kits','shop')}</div>${slider('Outer tire radius',12,9,16,' in','data-tune="true"')}<p class="tiny muted">Outside rubber radius, not rim diameter. Installed wheel/tire hardware still sets permitted adjustment.</p>${slider('Payload / ballast',0,0,250,' kg','data-tune="true"')}<details><summary>ECU / cam / AWD / limiter controls</summary><p>Installed equipment permissions apply. Fuel/ignition cuts, two-step, anti-lag, shift light and cam timing retain their separate settings.</p></details></div><div class="sticky-actions">${btn('Revert draft','data-revert="true"')}${btn('Apply changes','data-apply="true"','primary',state==='reserved')}</div>`,1)}${summaryPanel()}</div>`;}
function setups(){return title('Saved configurations','Blueprints, not owned parts')+metrics(true)+`<div class="grid">${panel('Library',`<div class="field"><label>Name ${options(['Engine + controls','Whole car','Tune only'],'Engine + controls')}</label><input type="text" aria-label="Configuration name" value="Street turbo setup"></div><div class="actions">${demo('Save applied configuration')}</div><div class="list" style="margin-top:14px">${item('Street turbo setup','Engine + controls · desired definitions retained',demo('Load preview')+demo('Delete blueprint'))}${item('Quarter-mile tune','Tune only · no hardware ownership',demo('Load tune preview'))}</div>`,1)}${panel('Load preview',`<p><strong>8 fitted kept · 2 spares reused · 1 missing</strong></p>${item('Injectors','Keep current fitted IDs and wear')}${item('Forged pistons','Reuse compatible owned set · 87% health')}${item('Programmable limiter','Missing · buy $240')}<div class="notice">Other affected fitted parts return to inventory. No donor is taken automatically.</div><div class="actions">${demo('Apply owned only','',true)}${demo('Buy missing + apply / $240','primary',state==='reserved')}</div>`,2)}</div>`;}
function maintenance(){return title('Installed parts & service')+stateNotice()+`<div class="grid three">${panel('Slots / attention',`<div class="list">${item('Rear brakes','FAILED · no rear braking','','selected')}${item('Clutch','42% health · excessive slip')}${item('Pistons / 4 units','One cylinder needs service')}${item('Radiator','88% health · small coolant leak')}${item('Engine controls','Limiter / two-step / shift light')}</div>`,1)}${panel('Selected component',`<h2>Rear brake pack</h2><p class="negative">Failed · braking reduced</p><p class="muted">Does not stop combustion or front-axle drive.</p>${stat('Condition','0%','',0,'negative')}${stat('Braking capacity','Reduced','',20,'negative')}<div class="actions">${route('Compare alternatives','shop')}${demo('Buy + install same set / $180','primary',state==='reserved')}${route('Use compatible spare','inventory')}</div><details><summary>Individual positions / details</summary><p>Engine and tire units support targeted replacement. Brake/wheel hardware currently remains a complete set.</p></details><p class="tiny muted">Removed failed original remains inventory.</p>`,2)}${panel('Fluids & services',`<p>Fuel 42 / 50 L · 8 L free</p><label>Add litres <input type="number" id="refuel-quantity" min="0" max="8" value="5" aria-label="Refuel quantity"></label><div class="actions">${demo('Review refuel cost','primary',state==='reserved')}</div><div class="field">Oil 3.8 / 4.5 L · condition 73%<div class="actions">${demo('Top up oil')}${demo('Change oil / service')}</div></div><div class="field">Coolant 4.1 / 5.0 L · leak active<div class="actions">${demo('Top up coolant')}${demo('Repair eligible radiator')}</div></div><div class="field">Rebuild estimate · $1,200 / 20 min<div class="actions">${btn('Review rebuild','data-confirm="rebuild"')}</div></div><small>Top-up adds quantity only; repairs obey the existing component eligibility rules.</small>`,3)}</div>`;}
function inventory(){return title('Inventory','Real items and condition')+`<div class="grid three">${panel('Containers',`<div class="list">${item('Garage shelves','Loose parts / units','','selected')}${item('Storage shelves','Other stored assets')}${item('Kestrel #8A21','Installed slots')}${item('Stored engine #442F','Complete/partial tree')}</div><div class="field"><label>Show ${options(['All items','Compatible only','Current category'],'Compatible only')}</label><input type="text" placeholder="Find item or category" aria-label="Inventory search"></div>`,1)}${panel('Items',`<div class="list">${item('Standard piston set · #P102','4 pistons · 87% health · retained original',demo('Inspect')+demo('Stage move / install'))}${item('Single piston · #U411','Matching definition · loose, no cylinder assigned',demo('Choose installation position'))}${item('Rear-left tire · #T076','64% life · 35 °C · retains physical condition',demo('Reuse in matching position'))}${item('Stored engine #442F','Oil/coolant and child wear retained',route('Inspect engine tree','assemblies'))}</div>`,2)}${panel('Destination / command',`<label>Move to ${options(['Storage shelves','Kestrel #8A21','Kestrel #B147','Stored engine #442F'],'Kestrel #8A21')}</label><div class="notice">Fitment and reservations checked before commit. A donor may become incomplete.</div><div class="actions">${demo('Add move to cart','primary')}${demo('Add sale to cart')}${route('Review trade cart','shop')}</div><p class="tiny muted">Existing explicit immediate reuse remains available. Staging a command changes no ownership or cash.</p>`,3)}</div>`;}
function shop(){return title('Parts shop','Preview / no purchase yet')+metrics(true)+`<div class="tabs">${route('Installed','maintenance')}${route('Inventory','inventory')}${demo('New offers','primary')}${demo('Used / retained dealer stock')}</div><div class="grid three">${panel('Offers',`<div class="field"><label>Category ${options(['Pistons','Induction','Cooling','Clutch','Tires'],'Pistons')}</label></div><div class="list">${item('Forged piston set','4 units · stronger, heavier · compatible',btn('Compare','data-preview="true"')+btn('Add set / $400','data-add="true"','primary'),'selected')}${item('Standard piston set','4 units · lighter / lower strength',btn('Add set / $160','data-add="true"'))}${item('Used original set','87% health · real dealer item #P102',demo('Inspect worn item')+btn('Add used / $120','data-add="true"'))}</div><div class="field"><strong>Complete set selected</strong><p class="muted">One set = 4 pistons, not four sets.</p>${demo('Switch to individual piston')}<div class="row"><span>Quantity</span><input type="number" value="1" min="1" max="99" aria-label="Offer quantity"></div></div>`,1)}${summaryPanel()}${panel('Trade cart',`<div class="list">${item('Buy · forged piston set','1 set / 4 units · $400',`<label><input type="checkbox" checked> Install one complete set</label>`)}${item('Sell · used clutch #C018','Retains exact identity in dealer stock · −$80',demo('Remove line'))}${item('Move · single piston #U411','To Storage shelves · $0',demo('Remove move'))}</div><div class="field"><div class="row"><span>Charges</span><strong>$400</strong></div><div class="row"><span>Credits</span><strong>$80</strong></div><div class="row"><span>Net payment</span><strong>$320</strong></div><div class="row"><span>Cash after</span><strong>$4,500</strong></div></div><p id="cart-count">${cartCount} illustrative purchase/sale lines</p>${btn('Confirm all / buy, sell, move','data-confirm="cart"','primary',state==='reserved')}${demo('Clear cart')}<details><summary>Individual installation positions</summary><p>Loose purchase needs no position. When installing matching individual units select C1–C4; extras stay loose.</p><label><input type="checkbox"> Cylinder 1</label> <label><input type="checkbox"> Cylinder 2</label></details>`,3)}</div>`;}
function assemblies(){return title('Engines & valuation','Captured buyer quote')+`<div class="grid three">${panel('Actual engine tree',`<div class="list">${item('Engine #442F','Stored · partial · oil 3.8 L','','selected')}${item('Piston set #P102','4 units / one worn')}${item('Crankshaft #K218','92% health')}${item('Cylinder head','Missing valves / incomplete')}</div><div class="actions">${demo('Attach if compatible')}${route('Reuse loose hardware','inventory')}${demo('Detach attached engine')}</div>`,1)}${panel('Buyer quote',`<label>Buyer ${options(['Wholesale','Specialist','Collector'],'Specialist')}</label>${stat('Assembly offer','$1,440','',60)}<p>Comparable loose hardware: $1,280</p><p class="muted">Assembly demand adds value; missing valves and condition reduce it. Values are illustrative, not a new policy.</p><details open><summary>Price explanations</summary><p>Quality / condition / completeness / history / buyer demand.</p></details>${demo('Refresh captured quote')}<p class="tiny muted">Quote timestamp, validity and captured identities are visible before confirmation.</p>`,2)}${panel('Keep / dispose',`<h3>Chassis salvage preview</h3><label class="modal-choice"><input type="checkbox" checked> Keep attached engine and its descendants</label><label class="modal-choice"><input type="checkbox"> Keep selected road hardware</label><div class="notice">KEEP: engine tree, original wear and liquids.<br>SELL: chassis and quoted road parts only.</div>${btn('Review quoted sale','data-confirm="salvage"','primary',state==='reserved')}${route('Recovery after sale','business')}`,3)}</div>`;}
function career(){return title('Race selection','Entry terms before staging')+stateNotice()+`<div class="tabs">${demo('Career','primary')}${demo('Free race')}${demo('Practice / no payout')}${demo('Records')}</div><div class="grid">${panel('Current events',`<div class="list">${item('F qualification','¼ mile · entry $0 · first-win / repeat terms',demo('Select event'),'selected')}${item('D rival','REP / previous qualification needed',demo('View eligibility'))}${item('Naturally aspirated challenge','Current turbo build is ineligible',demo('Compare restrictions'))}</div><p class="tiny muted">Existing 21 events retained; no new roster implied.</p>`,1)}${panel('Selected event & build',`<h2>F qualification · Kestrel #8A21</h2><p>Distance: 402.336 m · AI: Normal</p><p>Entry: $0 · reward terms: first win / repeat shown separately</p><p>Launch / shifting / simulation assists come from independent preferences.</p><div class="notice ${state==='healthy'?'ok':'fail'}">${state==='healthy'?'Eligible · fitted build checked':'Entry blocked · '+(state==='reserved'?'car reserved':state==='empty'?'no car':'required repair / assembly')}</div><div class="actions">${btn('Review entry / stage','data-route="race"','primary',state!=='healthy')}${route('Choose owned car','cars')}${route('Driving settings','settings')}</div><details><summary>Last pass / records</summary><p>Reaction 0.212 s · ET 14.198 s · trap 157 km/h · illustrative</p><p>60 ft / available eighth and quarter-mile splits.</p></details>`,2)}</div>`;}
function business(){return title('Business & recovery','Capped offline income')+`<div class="grid equal">${panel('Garage income',`<div class="summary"><div><small>Claimable</small><strong>$180</strong></div><div><small>Rate</small><strong>$60/h</strong></div><div><small>Cap</small><strong>8 h</strong></div><div><small>Bays</small><strong>1 / 2</strong></div></div><div class="actions">${demo('Claim captured income','primary')}${demo('Review expansion price')}</div><p class="muted">Claim settles the current rate contract; repeated claims cannot pay twice.</p>`,1)}${panel('Jobs / exact reservations',`${item('Display job · Kestrel #8A21','Engine and fitted components reserved · 12 min remaining',demo('Claim when ready','',true)+demo('Cancel / no payout'))}<div class="field"><label>Available offer ${options(['Display hatchback','Display pickup'],'Display pickup')}</label><label>Car ${options(['AWD pickup #E802','Kestrel #B147'],'AWD pickup #E802')}</label>${demo('Review assignment terms')}</div><p class="tiny muted">Parked jobs consume no driving fuel or wear.</p>`,2)}</div><div style="margin-top:16px">${panel('Recovery work',`<p>Available even with an empty garage or all cars broken.</p><p>Bounded real-time work → claim cash → buy fuel, repair or replace.</p><div class="actions">${demo('Start recovery work','primary')}${demo('Claim completed work')}${route('Replacement cars','cars')}${route('Repair / refuel','maintenance')}</div>`,3)}</div>`;}
function race(){return title('Practice / quarter mile','Neutral staging · no payout')+`<div class="pin"><div class="row"><h2>${a(1)}GEAR N · 0 km/h · 3,500 RPM</h2><span class="spacer"></span><span class="shift-light">SHIFT LIGHT · armed 6,700 RPM</span></div><div class="rpm-meter"><span></span></div><div class="row"><span>Boost 0.25 bar / 3.6 psi</span><span>Wheel slip 0%</span><span>Clutch slip 0 RPM</span></div></div><div class="track"><div class="lane"></div>${car()}<div class="lights" aria-label="Staging lights"><span></span><span></span><span></span><span></span></div></div><div class="notice ok">${a(2)}Neutral / staging brake hold · Hold W/Space to rev · E engages under launch rules</div><div class="actions">${demo('Warm-up / burnout')}${demo('Ready / Enter')}${btn('Pause','data-confirm="pause"')}${route('Show result preview','results')}</div><div class="pedals" style="margin-top:14px">${btn('Hold throttle / W / Space','data-pedal="Throttle"','pedal')}${btn('Hold clutch / Shift','data-pedal="Clutch"','pedal')}${btn('Hold brake / S','data-pedal="Brake"','pedal')}</div><div class="actions" style="margin-top:12px">${demo('Q · shift down')}${demo('E · engage / shift up')}<span>${a(3)}Pedals stay held across shift actions</span></div><details><summary>Advanced diagnostics</summary><p>Engine vs shaft torque, front/rear/individual wheel slip, converter/CVT, fluid pressures, temperatures, failures and fuel remaining.</p></details>`;}
function results(){return title('Pass result','Illustrative settled result')+metrics()+`<div class="grid equal">${panel('Timing & settlement',`<table><tr><th>Reaction</th><td>0.212 s</td></tr><tr><th>Elapsed time</th><td>14.198 s</td></tr><tr><th>60 ft</th><td>2.314 s</td></tr><tr><th>⅛ mile</th><td>9.240 s</td></tr><tr><th>Trap speed</th><td>157 km/h</td></tr><tr><th>Reward status</th><td>Practice · $0 · no payout</td></tr></table>`,1)}${panel('Condition / next action',stateNotice()+`<p>Fuel used 0.19 L · component wear and temperatures retained.</p><p>Temperature at next entry follows your selected start rule; retries do not repair condition.</p><div class="actions">${route('Repair affected parts','maintenance')}${route('Run again','race','primary')}${route('Garage','garage')}${demo('Export telemetry CSV')}</div>`,2)}</div>`;}
function settings(){const tabs=['Audio','Units','Driving','Simulation','Controls','Reset'];let body='';if(settingTab==='Audio')body=slider('Master volume',75,0,100,'%')+slider('Opponent sounds',70,0,100,'%')+'<p class="muted">Opponent gain follows the shared master and distance attenuation.</p><div class="row"><span>Generated output meter</span><strong>Available in live bench</strong></div>';if(settingTab==='Units')body='<div class="field"><label>Speed '+options(['km/h','mph','m/s'],'km/h')+'</label></div><div class="field"><label>Pressure '+options(['bar','psi','kPa'],'bar')+'</label></div><div class="field"><label>Torque '+options(['Nm','lb-ft'],'Nm')+'</label></div><p>Boost retains bar/psi. Tire outer radius includes rubber and is shown in inches.</p>';if(settingTab==='Driving')body='<div class="field"><label>Driving preset '+options(['Automatic','Sequential shifts','Manual clutch'],'Sequential shifts')+'</label></div><div class="field"><label>Launch '+options(['Automatic','Assisted','Manual'],'Assisted')+'</label></div><div class="field"><label>Shift operation '+options(['Automatic','Shift myself','Manual clutch'],'Shift myself')+'</label></div><p>Hardware gearbox type is separate from who operates it.</p>';if(settingTab==='Simulation')body=`<div class="field"><label>Preset ${options(['Arcade','Balanced','Simulation','Custom'],'Custom')}</label></div><div class="field"><label><input id="heat-managed" type="checkbox" checked> Heat management</label><p class="tiny muted">Turning OFF keeps heat optimal throughout driving.</p></div><div class="field"><label>Race-entry temperatures <select id="start-temps"><option>Fully cooled / ambient</option><option>Optimal at start only</option><option>Live / real elapsed cooling</option></select></label><small id="heat-note">Heat then evolves during driving.</small></div>${['Wear','Fuel use','Oil/coolant depletion','Oil aging','Condition effects'].map(v=>`<div class="field"><label>${v} ${options(['None / assisted','Reduced · 25%','Full / realistic'],'Reduced · 25%')}</label></div>`).join('')}<details><summary>Driving assists / top-up / warm-up</summary>${['Clutch assist','Stall prevention','Traction control','Rev match','Optional warm-up'].map(v=>`<label class="modal-choice"><input type="checkbox"> ${v}</label>`).join('')}<p>Top-up: Manual / Automatic, paid and bounded in the player garage.</p></details>`;if(settingTab==='Controls')body='<table><tr><th>Throttle</th><td>W / Space</td><td>'+demo('Rebind throttle')+'</td></tr><tr><th>Engage / upshift</th><td>E / Up</td><td>'+demo('Rebind shift')+'</td></tr><tr><th>Downshift</th><td>Q / Down</td><td>'+demo('Rebind down')+'</td></tr><tr><th>Clutch</th><td>Left Shift</td><td>'+demo('Rebind clutch')+'</td></tr><tr><th>Brake</th><td>S</td><td>'+demo('Rebind brake')+'</td></tr></table><p class="muted">Conflict checking, controller axes and equivalent fine/reset actions are later implementation gates.</p>';if(settingTab==='Reset')body='<div class="notice fail">Reset progression, career, cars, inventory and saved configurations.</div><p>Keep driving, volume, units and input preferences.</p>'+btn('Review game reset','data-confirm="reset"','danger');return title('Settings','Shared preferences')+`<div class="grid">${panel('Preference pages',`<div class="tabs">${tabs.map(t=>btn(t,`data-settings-tab="${t}"`,t===settingTab?'active':'')).join('')}</div>${body}`,1)}${panel('Preference feedback',`<p>All races and benches use the same audio and unit preferences.</p><p>Settings gestures save when completed; bindings and display refresh never publish a tuning draft.</p><p>Advanced rules remain independently selectable. Disabled choices explain their dependency and retain the remembered preference.</p><div class="notice">${a(2)}Race-start optimal temperatures and continuous optimal heat are different controls.</div><p>${a(3)}Reset is a separate confirmation dialog, never a click-through accident.</p>`,2)}</div>`;}
function bench(physical){const mode=physical?'Shared road simulation':'Acoustic / dyno fixture';const tabs=physical?['Drive','Parts','Condition','Fluids','Rules','Scenarios','Files']:['Drive','Engine','Induction','Exhaust','Gearbox / wheels','Mix','Scenarios','Files'];let controls='';if(benchTab==='Drive')controls=`<div class="row"><strong>Input source: <span id="owner-label">${driveOwner}</span></strong>${btn('Use sliders','data-owner="Sliders"')}${btn('Use keyboard','data-owner="Keyboard"')}</div><p class="tiny muted">Live drive fields show feedback in keyboard mode; config tabs remain editable.</p>${slider('Throttle',30,0,100,'%','data-drive-slider="true"',driveOwner!=='Sliders')}${slider('Clutch pedal',0,0,100,'%','data-drive-slider="true"',driveOwner!=='Sliders')}${slider('Brake',0,0,100,'%','data-drive-slider="true"',driveOwner!=='Sliders')}${physical?'<p>RPM is physical feedback. No RPM pin in road mode.</p>':`<label class="modal-choice"><input type="checkbox"> Fixed-RPM diagnostic</label>${slider('Target RPM',3500,900,9000,' RPM')}${slider('Dyno load',50,0,100,'%')}<p class="tiny muted">Fixed RPM/load/slip are fixture overrides.</p>`}`;
if(benchTab==='Engine')controls=slider('Cylinders',8,3,12)+slider('Displacement',57,10,80,' /10 L')+`<div class="field"><label>Fuel system ${options(['Carburetor','Injection'],'Carburetor')}</label></div>`+slider('Flywheel mass',12,1,35,' kg')+'<details><summary>All spec / torque / behavior fields</summary><p>Complete field index is retained in Control coverage, including cam overlap, warmup, limiter, cuts and launch controls.</p></details>';
if(benchTab==='Induction')controls=`<div class="field"><label>Arrangement ${options(['Naturally aspirated','Single turbo','Twin turbo','Single supercharger','Twin supercharger','Turbo + supercharger'],'Single turbo')}</label></div>`+slider('Turbo unit size',100,50,200,'%')+slider('Boost reference',74,0,200,' /100 bar')+slider('Spool time',50,5,200,' /100 s')+`<div class="field"><label>Blow-off valve ${options(['Recirculated','Hiss','Chirp','Flutter'],'Chirp')}</label></div><p class="tiny muted">Independent of keyboard pedal ownership.</p>`;
if(benchTab==='Exhaust')controls=`<div class="actions">${demo('Quiet')}${demo('Chambered')}${demo('Absorptive')}${demo('Open')}</div><div class="item"><h3>1 · Catalyzer</h3>${slider('Amount',65,0,100,'%')}${slider('Attenuation',7,0,20,' dB')}${demo('Move earlier')}${demo('Remove element')}</div><div class="item"><h3>2 · Absorptive silencer</h3>${slider('Pulse softening',30,0,100,'%')}${slider('Resonance frequency',140,40,800,' Hz')}</div>${demo('Add acoustic component')}`;
if(benchTab==='Mix')controls=slider('Engine gain',75,0,100,'%')+slider('Idle boost',6,-6,12,' dB')+slider('Turbo gain',25,0,100,'%')+slider('Supercharger whine',35,0,100,'%')+slider('Blow-off gain',40,0,100,'%')+slider('Exhaust bass',70,0,100,'%')+'<p>Master volume stays shared on Settings. Capture/WAV reference gain is labelled separately.</p>';
if(benchTab==='Gearbox / wheels')controls=`<div class="field"><label>Transmission ${options(['Manual · H-pattern','Manual · sequential','DCT','Automatic / converter','CVT'],'Manual · H-pattern')}</label></div>`+slider('Gear 1 ratio',36,10,60,' /10')+slider('Gear 2 ratio',22,10,50,' /10')+slider('Wheel assembly mass',20,5,50,' kg')+'<p>Independent rotating mass and outer rubber radius.</p>';
if(benchTab==='Parts')controls=`<label>Test category ${options(['Pistons','Induction','Clutch','Differential','Tires'],'Clutch')}</label>${item('Wet multiplate clutch','Isolated test hardware · replacement resets this run',demo('Test compatible part'))}${item('Dry single plate','Different capacity, cooling and service behavior',demo('Test compatible part'))}${demo('Remove selected test part')}`;
if(benchTab==='Condition')controls=`<div class="field"><label>Component ${options(['Clutch','Pistons / cylinder 1','Rear tire / left','Driveshaft'],'Pistons / cylinder 1')}</label></div>${slider('Starting structural health',75,0,100,'%')}${slider('Starting temperature',90,20,500,' °C')}<div class="field"><label>Fault ${options(['None','Misfire','Leak','Bent valve'],'Misfire')}</label></div>${slider('Fault severity',40,0,100,'%')}<p class="tiny muted">Assign while paused or before engagement; source is retained. Applicable fault types depend on component.</p>${demo('Replace single test element')}`;
if(benchTab==='Fluids')controls=slider('Test oil quantity',38,0,45,' /10 L')+slider('Oil condition',73,0,100,'%')+slider('Test coolant',41,0,50,' /10 L')+slider('Leak severity',15,0,100,'%')+'<div class="actions">'+demo('Top up isolated oil')+demo('Top up isolated coolant')+demo('Parked cooldown')+'</div>';
if(benchTab==='Rules')controls=slider('Wear multiplier',10,0,100,'×')+`<div class="field"><label>Wear ${options(['None','Partial · 25%','Full'],'Full')}</label></div>`+slider('Front-left test grip',100,0,150,'%')+slider('Rear-left test grip',100,0,150,'%')+'<p>Multiplier accelerates wear, not physics time or heating. Installed downshift protection remains authoritative.</p>';
if(benchTab==='Scenarios')controls=`<div class="field"><label>Scenario ${options(physical?['Full pull / shifts / coast / brake','Unsafe manual downshift','Neutral flywheel decay','Seeded driver']:['Neutral blips','Two-step bounce','Loaded pull / shifts','Flywheel coast-down'],'Full pull / shifts / coast / brake')}</label></div><div class="actions">${demo('Run current scenario')}${demo('Repeat captured')}${demo('Capture A')}${demo('Capture B')}${demo('Run A')}${demo('Run B')}</div><p>Captured inputs, hardware and initial state repeat on the same model. Live sound callback timing is not sample-exact.</p>`;
if(benchTab==='Files')controls='<label>Export folder <input type="text" value="Local test captures" aria-label="Export folder"></label><div class="actions">'+demo('Export CSV + config')+demo('Import capture')+demo(physical?'Export replay JSON':'Export matching A/B WAV')+'</div><p>Model version, captured setup and full chronological trace stay attached to the export.</p>';
return title(physical?'Physical driving bench':'Engine / sound bench',mode)+`<div class="test-banner">ISOLATED TEST COPY · no player money, wear, parts or resources changed</div><div class="grid">${panel('Test controls',`<div class="tabs">${tabs.map(t=>btn(t,`data-bench-tab="${t}"`,t===benchTab?'active':'')).join('')}</div><div class="scroll">${controls}</div>`,1)}${panel('Live state / chronological graph',`<div class="summary"><div><small>RPM</small><strong>3,500</strong></div><div><small>Gear</small><strong>N</strong></div><div><small>Wheel slip</small><strong>0%</strong></div><div><small>Clutch slip</small><strong>0 RPM</strong></div></div>${dyno(true)}<div class="row"><label><input type="checkbox" ${physical?'':'checked'}> ${physical?'Record input / trace · OFF by default':'Record dyno trace'}</label>${demo('End recording')}${demo('Export')}</div><div class="actions">${demo('Run A visible')}${demo('Run B visible')}${demo('Clear old overlays')}</div><details><summary>Detailed telemetry / channel groups</summary><p>Engine/shaft power, wheel/contact/load, flywheel energy, boost/spool, converter/CVT, individual failures, fuel, oil/coolant, temperatures and wear.</p></details>`,2)}</div><div class="pin" style="margin-top:16px"><div class="actions">${demo('Reset test / R')}${demo('Neutral / N')}${demo('Q · shift down')}${demo('E · engage / shift up')}${demo('Pause / Esc')}${demo(physical?'Reset wear / heat only':'Restore valid config')}${physical?'':demo('Dyno concert / random classic')}</div><div class="pedals" style="margin-top:10px">${btn('Hold gas / W / Space','data-pedal="Throttle"','pedal')}${btn('Hold clutch / Shift','data-pedal="Clutch"','pedal')}${btn('Hold brake / S','data-pedal="Brake"','pedal')}</div><div class="actions" style="margin-top:10px">${route('Shared audio / units','settings')}${route(physical?'Sound fixture':'Physical road bench',physical?'sound':'physical')}${route('Return to garage','garage')}</div></div>`;
}
function coverage(){return title('Migration control coverage','Static source inventory')+`<div class="notice">${a(1)}Source-backed controls and field templates. Runtime binding and usability acceptance remain in their destination phases.</div><input type="text" id="coverage-search" class="coverage-search" placeholder="Find control, field, source or phase (e.g. twoStep, Exhaust, 4N)" aria-label="Search coverage"><p id="coverage-count" class="muted"></p><div class="coverage-table"><table><thead><tr><th>Destination</th><th>Source</th><th>Control / field expression</th></tr></thead><tbody id="coverage-rows"></tbody></table></div><p class="tiny muted">First 80 matches shown for readability. Complete tracked inventory has full expressions and source hashes.</p>`;}
function render(){const [name,phase]=views[current];$('screen-picker').value=current;$('scope-label').textContent=['sound','physical'].includes(current)?'Isolated development copy · '+(current==='sound'?'fixture overrides':'shared race simulation'):'Player garage · saved owned car';$('car-header').textContent=state==='empty'?'No owned car · recovery available':'Kestrel 2.0T · #8A21';$('screen').innerHTML=({garage,cars,tuning,setups,maintenance,inventory,shop,assemblies,career,business,race,results,settings,sound:()=>bench(false),physical:()=>bench(true),coverage}[current])();$('annotations').innerHTML=`<div><h3>${phase} · ${name}</h3><p>Illustrative layout. Unity implementation and user acceptance remain pending.</p></div>`+Array.from({length:3},(_,i)=>`<div><h3>${i+1}. ${annotations[current][i*2]}</h3><p>${annotations[current][i*2+1]}</p></div>`).join('');document.querySelectorAll('#navigation [data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===current));if(current==='coverage')filterCoverage('');}
function navigate(screen){if(current==='tuning'&&screen!==current)draftDirty=false;if(screen==='physical'||screen==='sound')benchTab='Drive';current=screen;render();$('screen').focus({preventScroll:true});}
function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3200);}
function confirm(kind){const content={cart:['Trade confirmation','Buy $400 · sell $80 · move $0 → net $320. Replacements return originals to inventory. Existing quote validation and one recoverable publication happen in Unity.'],salvage:['Keep engine / salvage chassis','Keep engine tree and its oil/coolant/condition. Only quoted chassis/road assets leave ownership. Stale or failed confirmation leaves everything intact.'],rebuild:['Send engine to rebuild shop','Review captured price and real-time deadline. This exact engine is reserved until collection; compatible cars remain independent.'],reset:['Reset game progression','Reset career, cars, inventory and tunes to the authored $1,200 / starter-car new game. Keep driving, audio, units and bindings. This layout review resets no real save.'],purchase:['Buy another car instance','Review exact package price, initial resources and reputation requirements. New copy has independent owned component IDs.'],pause:['Race paused','Audio and units are shared. Resume is deliberate; returning focus does not resume the race.']}[kind];$('dialog-content').innerHTML=`<h2>${content[0]}</h2><p>${content[1]}</p><div class="notice">Layout review only · no game transaction</div><div class="actions">${demo('Confirm preview only','primary')}${route('Open relevant settings','settings')}</div>`;$('review-dialog').showModal();}
function filterCoverage(query){const q=query.toLowerCase();const rows=(window.DragLab4AControls||[]).filter(r=>r.join(' ').toLowerCase().includes(q));$('coverage-count').textContent=`${rows.length} matching source / field templates`;$('coverage-rows').innerHTML=rows.slice(0,80).map(r=>`<tr><td>${escapeHtml(r[0])}</td><td>${escapeHtml(r[1])}:${r[2]}</td><td><code>${escapeHtml(r[3])}</code></td></tr>`).join('');}
function escapeHtml(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
$('screen-picker').innerHTML=Object.entries(views).map(([k,[n,p]])=>`<option value="${k}">${p} · ${n}</option>`).join('');
$('navigation').innerHTML=[['Garage','garage'],['Cars','cars'],['Workshop','maintenance'],['Inventory','inventory'],['Shop / cart','shop'],['Tuning','tuning'],['Race','career'],['Business','business'],['Settings','settings']].map(([n,r])=>route(n,r)).join('')+'<div class="divider"></div>'+route('Sound bench','sound')+route('Physical bench','physical')+route('Coverage map','coverage');
$('screen-picker').addEventListener('change',e=>navigate(e.target.value));$('state-picker').addEventListener('change',e=>{state=e.target.value;render();});$('width-picker').addEventListener('change',e=>{const v=e.target.value;$('prototype').style.maxWidth=v==='fluid'?'1500px':v+'px';$('prototype').className=v==='960'?'review-width-960':'';});$('annotations-toggle').addEventListener('click',e=>{const shown=e.target.getAttribute('aria-pressed')!=='true';e.target.setAttribute('aria-pressed',String(shown));e.target.textContent=shown?'Annotations on':'Annotations off';$('annotations').hidden=!shown;document.body.classList.toggle('annotations-off',!shown);});$('close-dialog').addEventListener('click',()=>$('review-dialog').close());
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.route){if($('review-dialog').open)$('review-dialog').close();navigate(b.dataset.route);}if(b.dataset.demo)toast('Preview only: '+b.dataset.demo);if(b.dataset.confirm)confirm(b.dataset.confirm);if(b.dataset.settingsTab){settingTab=b.dataset.settingsTab;render();}if(b.dataset.benchTab){benchTab=b.dataset.benchTab;render();}if(b.dataset.owner){driveOwner=b.dataset.owner;render();}if(b.dataset.add){cartCount++;$('cart-count').textContent=cartCount+' illustrative purchase/sale lines';toast('Layout selection added; demo prices and curves are illustrative.');}if(b.dataset.preview)toast('Comparison visible; curve values are illustrative.');if(b.dataset.apply){draftDirty=false;render();toast('Draft applied in this mockup only.');}if(b.dataset.revert){draftDirty=false;render();toast('Mock draft restored.');}});
document.addEventListener('input',e=>{if(e.target.type==='range'){const output=e.target.closest('.field')?.querySelector('output');if(output)output.textContent=e.target.value;if(e.target.dataset.tune){draftDirty=true;document.querySelector('.page-title .badge').textContent='UNAPPLIED DRAFT';}}if(e.target.id==='coverage-search')filterCoverage(e.target.value);if(e.target.id==='refuel-quantity'){const v=Number(e.target.value);if(Number.isFinite(v))e.target.value=String(Math.min(8,Math.max(0,v)));}});
document.addEventListener('change',e=>{if(e.target.id==='heat-managed'){$('start-temps').disabled=!e.target.checked;$('heat-note').textContent=e.target.checked?'Heat then evolves during driving.':'Continuous optimal heat: remembered start preference is inactive.';}});
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-pedal]');if(!b)return;b.setPointerCapture(e.pointerId);b.classList.add('active');b.textContent=b.dataset.pedal+' held · preview';});document.addEventListener('pointerup',e=>{const b=e.target.closest('[data-pedal]');if(!b)return;b.classList.remove('active');b.textContent='Hold '+b.dataset.pedal.toLowerCase()+' · preview';});document.addEventListener('pointercancel',()=>document.querySelectorAll('[data-pedal]').forEach(b=>b.classList.remove('active')));
render();
